export function translateDocumentation(sections) {
 const translated = structuredClone(sections);
 for (const section of translated) {
  const en = english[section.id];
  if (!en || en.blocks.length !== section.blocks.filter(b=>b.type!=='editorial-image').length) throw new Error(`Incomplete English documentation: ${section.id}`);
  section.title = en.title; section.lead = en.lead;
  const originalBlocks = section.blocks.filter(b=>b.type!=='editorial-image');
  originalBlocks.forEach((block,i)=>{
   const text = en.blocks[i];
   if (block.type==='sources') {
    // Official document names, repository paths and contract names stay unchanged.
    return;
   }
   if(!text || !text.title) throw new Error(`Missing English block ${section.id}/${i}`);
   block.title = text.title;
   if(block.type==='prose') {
    if(!text.paragraphs || text.paragraphs.length!==block.paragraphs.length) throw new Error(`Paragraph mismatch ${section.id}/${i}`);
    block.paragraphs=text.paragraphs;
   }
   if(block.type==='flow') {
    if(!text.nodes || text.nodes.length!==block.nodes.length) throw new Error(`Flow mismatch ${section.id}/${i}`);
    block.nodes=text.nodes;
   }
   if(block.type==='concepts') {
    if(!text.items || text.items.length!==block.items.length) throw new Error(`Concept mismatch ${section.id}/${i}`);
    block.items=text.items;
   }
   if(block.type==='arsenal') {
    if(!text.items || text.items.length!==block.items.length) throw new Error(`Arsenal mismatch ${section.id}/${i}`);
    block.caption=text.caption;
    block.items.forEach((item,j)=> {item.purpose=text.items[j].purpose; if(item.objective==='Contrato declarado por el módulo (string)')item.objective='Module-declared contract (string)';});
   }
   if(block.type==='code') block.caption=text.caption;
  });
  section.kicker = section.kicker.replace('ARQUITECTURA','ARCHITECTURE').replace('CONSTRUCCIÓN','CONSTRUCTION').replace('PLATAFORMA','PLATFORM').replace('MATERIAL Y CERTIFICACIÓN','MATERIAL AND CERTIFICATION').replace('GOBERNANZA','GOVERNANCE');
 }
 return translated;
}
